command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main work/shell-provider-copyout-20261007 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne "700500d92442f25002fb707031d7c2ff2cb2052f"){throw "main moved"}
if((& git rev-parse refs/remotes/origin/work/shell-provider-copyout-20261007).Trim() -ne "9b468483d7dc259564a142396d7ee29f123ede73"){throw "candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "checkout dirty"}
& git switch --detach 9b468483d7dc259564a142396d7ee29f123ede73
if($LASTEXITCODE -ne 0){throw "checkout failed"}
& .\test.bat policy
if($LASTEXITCODE -ne 0){throw "policy failed"}
& git diff --check 700500d92442f25002fb707031d7c2ff2cb2052f 9b468483d7dc259564a142396d7ee29f123ede73
if($LASTEXITCODE -ne 0){throw "diff check failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "restore main failed"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "restore main ff failed"}
Write-Host "SHELL_PROVIDER_COPYOUT_DOCS_POLICY=PASS"
